#!/bin/bash
# Installs the GPU pool dashboard on a Mac:
#   ~/.gpu-pool/scripts         the dashboard (pool_serve.py and friends)
#   ~/.local/bin/dashboard      terminal command; `dashboard stop` ends a running one
#   ~/Desktop/GPU Dashboard.app double-click to start it in the background and open it
# Build it from a checkout with:  python3 mac/build_installer.py --out install.sh
# then run:  bash install.sh   (or copy install.sh to another Mac and run it there)
# Generated by mac/build_installer.py; edit mac/install_template.sh instead.
set -euo pipefail
dest="$HOME/.gpu-pool"
bin="$HOME/.local/bin"
app="$HOME/Desktop/GPU Dashboard.app"
# Unpack over the existing copy: shipped files are replaced, and files other
# tools added to scripts/ (they may depend on it) are left alone.
mkdir -p "$dest/scripts" "$bin"
base64 --decode > "$dest/scripts.tar.gz" <<'ARCHIVE'
@@SCRIPTS@@
ARCHIVE
tar -xzf "$dest/scripts.tar.gz" -C "$dest"
rm "$dest/scripts.tar.gz"
# Hosts left out of the default selection (one alias or glob per line); kept across installs.
[ -f "$dest/hide" ] || printf '# Hosts left out of the default dashboard selection, one alias or glob per line.\n' > "$dest/hide"

cat > "$bin/dashboard" <<'WRAPPER'
#!/bin/bash
# GPU pool live dashboard: tracks hosts from ~/.ssh/config (pick them in the Servers panel).
# Examples: dashboard | dashboard --hosts 'gpu-*' | dashboard --list | dashboard stop
server="$HOME/.gpu-pool/scripts/pool_serve.py"
if [ "${1:-}" = stop ]; then
  pkill -f "$server" && echo "dashboard stopped" || echo "dashboard was not running"
  exit 0
fi
exec python3 "$server" "$@"
WRAPPER
chmod +x "$bin/dashboard"

# Desktop app: a bundle whose executable is a shell script. It starts the
# server through a login shell so ssh sees the same PATH, agent and proxy
# tools as the terminal, then opens the page; a second launch only reopens it.
rm -rf "$app"
mkdir -p "$app/Contents/MacOS" "$app/Contents/Resources"
cat > "$app/Contents/Info.plist" <<'PLIST'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>CFBundleName</key><string>GPU Dashboard</string>
  <key>CFBundleDisplayName</key><string>GPU Dashboard</string>
  <key>CFBundleIdentifier</key><string>local.gpu-pool.dashboard</string>
  <key>CFBundleExecutable</key><string>launcher</string>
  <key>CFBundleIconFile</key><string>AppIcon</string>
  <key>CFBundlePackageType</key><string>APPL</string>
  <key>CFBundleVersion</key><string>1</string>
  <key>LSUIElement</key><true/>
</dict>
</plist>
PLIST
cat > "$app/Contents/MacOS/launcher" <<'LAUNCHER'
#!/bin/bash
port=8765
url="http://127.0.0.1:$port/"
log="$HOME/.gpu-pool/dashboard.log"
up() { curl -s -o /dev/null --max-time 1 "$url"; }
if ! up; then
  nohup /bin/zsh -lic "exec dashboard --no-browser --port $port" > "$log" 2>&1 < /dev/null &
  for _ in $(seq 40); do up && break; sleep 0.25; done
fi
if up; then
  open "$url"
else
  osascript -e "display alert \"GPU Dashboard did not start\" message \"See $log\""
fi
LAUNCHER
chmod +x "$app/Contents/MacOS/launcher"

base64 --decode > "$dest/icon.png" <<'ICON'
@@ICON@@
ICON
iconset="$(mktemp -d)/AppIcon.iconset"
mkdir -p "$iconset"
for size in 16 32 128 256 512; do
  sips -z "$size" "$size" "$dest/icon.png" --out "$iconset/icon_${size}x${size}.png" > /dev/null
  sips -z $((size * 2)) $((size * 2)) "$dest/icon.png" --out "$iconset/icon_${size}x${size}@2x.png" > /dev/null
done
iconutil -c icns "$iconset" -o "$app/Contents/Resources/AppIcon.icns"
rm -rf "$(dirname "$iconset")"
codesign --force --sign - "$app" 2> /dev/null || true
touch "$app"

case ":$PATH:" in
  *":$bin:"*) ;;
  *)
    rc="$HOME/.zshrc"
    [ "${SHELL##*/}" = bash ] && rc="$HOME/.bash_profile"
    grep -qs 'gpu-pool dashboard' "$rc" || \
      printf '\nexport PATH="$HOME/.local/bin:$PATH"  # gpu-pool dashboard\n' >> "$rc"
    echo "Added ~/.local/bin to PATH in $rc; open a new terminal or run: source $rc"
    ;;
esac
# A server started before this install still runs the old code.
pkill -f "$dest/scripts/pool_serve.py" && echo "Stopped the running dashboard; start it again to load this version." || true
echo "Installed. Selected hosts:"
"$bin/dashboard" --list || true
echo "Start it by double-clicking 'GPU Dashboard' on the Desktop, or run: dashboard"
echo "Stop the background server with: dashboard stop"
